window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[31]={"id":"031","numero":31,"titre":"Accouchement normal","objectifs":[{"id":"31-1","rang":"A","rubrique":"Définition","titre":"Connaître les différents éléments du bassin maternel","contenu":"<p>Le <span class=\"kw-def\">bassin maternel</span> est la structure osseuse qui constitue la <strong>filière pelvienne obstétricale</strong>. Sa connaissance anatomique conditionne la compréhension de l’engagement, de la descente et du dégagement du mobile fœtal.</p>\n\n      <h4>Ceinture pelvienne — anneau ostéo-articulaire</h4>\n\n      <ul>\n        <li><strong>4 os :</strong> 2 os coxaux + sacrum + coccyx</li>\n        <li><strong>4 articulations</strong> (très peu mobiles) : 2 articulations sacro-iliaques + symphyse pubienne + articulation sacro-coccygienne</li>\n      </ul>\n\n      <h4>Filière pelvienne — 3 étages</h4>\n\n      <table >\n        <thead>\n          <tr><th>Étage</th><th>Repères &amp; diamètres</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Détroit supérieur (DS)</strong><br><em>= cylindre d’engagement de Demelin</em></td>\n            <td>\n              <strong>Limites :</strong>\n              <ul>\n                <li>Avant : bord supérieur de la symphyse pubienne</li>\n                <li>Arrière : <span class=\"kw-clinique\">promontoire</span> (disque vertébral L5–S1, <span class=\"kw-chiffre\">9 cm</span> au-dessus de SP)</li>\n                <li>Latéralement : lignes innominées</li>\n              </ul>\n              <strong>Forme :</strong> cœur de carte à jouer (rétréci en sagittal par la saillie du promontoire)<br>\n              <strong>Diamètres :</strong>\n              <ul>\n                <li>Promonto-rétropubien : <span class=\"kw-chiffre\">10,5 cm</span></li>\n                <li>Transverse médian : <span class=\"kw-chiffre\">12,5 cm</span></li>\n              </ul>\n              <strong>Axe :</strong> oblique en arrière et en bas, vise l’interligne sacro-coccygien\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Excavation pelvienne</strong><br><em>= canal pelvien / petit bassin</em></td>\n            <td>\n              <strong>Limites :</strong>\n              <ul>\n                <li>Hautes/basses : entre cylindre d’engagement et détroit inférieur</li>\n                <li>Avant/arrière : symphyse pubienne ↔ face antérieure du sacrum</li>\n                <li>Latéralement : face interne de l’os iliaque + relief des <strong>épines sciatiques</strong></li>\n              </ul>\n              <strong>Diamètres :</strong>\n              <ul>\n                <li>Constant à tous les plans : <span class=\"kw-chiffre\">≈ 12 cm</span></li>\n                <li>Bisciatique/biépineux : <span class=\"kw-chiffre\">10,5 cm</span> (<em>≠ bi-ischiatique</em>)</li>\n              </ul>\n              <strong>Détroit moyen :</strong> à l’union du 1/3 inférieur et des 2/3 supérieurs, passe par les 2 épines sciatiques<br>\n              <strong>Forme :</strong> cylindre coudé (segment de tore) avec 2 rétrécissements (promontoire + épines sciatiques)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Détroit inférieur (DI)</strong><br><em>= plan de dégagement</em></td>\n            <td>\n              <strong>Forme :</strong> prisme triangulaire\n              <ul>\n                <li>Face supérieure : plan du détroit moyen</li>\n                <li>Face antérieure : oblique bas/arrière, joint bord inférieur du pubis aux ischions</li>\n                <li>Face postérieure : oblique haut/arrière, déterminée par les 2 ischions et la pointe du coccyx</li>\n              </ul>\n              <strong><span class=\"kw-clinique\">Diamètre</span> bi-ischiatique :</strong> <span class=\"kw-chiffre\">12 cm</span> (principale mesure ; <em>≠ bi-sciatique</em>)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Périnée — diaphragme pelvi-périnéal</h4>\n\n      <ul>\n        <li>Bassin mou = <strong>vagin + diaphragme pelvi-périnéal</strong></li>\n        <li>Expulsion = traversée du périnée sous l’influence des <span class=\"kw-clinique\">CU + poussée abdominale maternelle</span></li>\n        <li><strong>Plan profond :</strong> faisceaux du muscle élévateur de l’anus + ligament sacrotubéral</li>\n        <li><strong>Plan superficiel :</strong> muscles du périnée superficiel</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Présentation engagée.</strong> Une présentation est dite engagée lorsque <strong>le plus grand <span class=\"kw-clinique\">diamètre</span> de la présentation a franchi le plan du DS</strong> (= diamètre bipariétal de <span class=\"kw-chiffre\">9,5 cm</span> en présentation céphalique).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — <span class=\"kw-ci\">Grossesse</span> extra-utérine · 23 — Grossesse normale · 24 — Complications de la grossesse</em></p>","frequence":0},{"id":"31-2","rang":"A","rubrique":"Définition","titre":"Connaître les repères du mobile fœtal","contenu":"<p>Le <span class=\"kw-def\">mobile fœtal</span> est un ovoïde à 2 pôles (pelvien + céphalique) pelotonné sur lui-même. Ses dimensions conditionnent la possibilité de franchissement de la filière pelvienne.</p>\n\n      <h4>Tête fœtale</h4>\n\n      <table >\n        <thead>\n          <tr><th>Caractéristique</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Forme</strong></td>\n            <td>Ovoïde — petite extrémité = <strong>menton</strong>, grosse extrémité = <strong>occiput</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Sutures</strong></td>\n            <td>\n              <ul>\n                <li>Suture longitudinale (sagittale) sur la ligne médiane</li>\n                <li>Sutures transversales antérieure et postérieure (coronale + lambdoïde)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Fontanelles</strong></td>\n            <td>\n              Au croisement entre suture longitudinale et transversale :\n              <ul>\n                <li><span class=\"kw-clinique\">Fontanelle antérieure</span> = <strong>bregma</strong> (bregmatique)</li>\n                <li><span class=\"kw-clinique\">Fontanelle postérieure</span> = <strong>lambda</strong> (lambdoïde)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Diamètres clés</strong></td>\n            <td>\n              <ul>\n                <li><strong>Bipariétal :</strong> <span class=\"kw-chiffre\">9,5 cm</span> — <span class=\"kw-clinique\">diamètre</span> du passage de la tête</li>\n                <li>Sous-occipito-bregmatique : <span class=\"kw-chiffre\">9,5 cm</span> (favorable à l’engagement, tête bien fléchie)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Corps fœtal</h4>\n\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-clinique\">Diamètre</span></th><th>Valeur</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Biacromial</strong></td><td><span class=\"kw-chiffre\">12 cm</span> réduit à <span class=\"kw-chiffre\">9,5 cm</span> par tassement (passage des épaules)</td></tr>\n          <tr><td>Bitrochantérien</td><td><span class=\"kw-chiffre\">9 cm</span></td></tr>\n          <tr><td>Bi-iliaque</td><td><span class=\"kw-chiffre\">8 cm</span></td></tr>\n          <tr><td>Sacro-pubien</td><td><span class=\"kw-chiffre\">7,5 cm</span></td></tr>\n          <tr><td>Sterno-dorsal</td><td><span class=\"kw-chiffre\">9,5 cm</span></td></tr>\n          <tr><td>Sacro-pré-tibial</td><td><span class=\"kw-chiffre\">12 cm</span> réduit à <span class=\"kw-chiffre\">9 cm</span> par tassement</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Présentation céphalique fléchie.</strong> Le <span class=\"kw-clinique\">diamètre</span> céphalique varie selon la flexion. <strong>Tête en flexion maximale</strong> sur le tronc = présentation céphalique fléchie = <strong>diamètre bipariétal</strong> qui conditionne l’engagement. L’accouchement est d’autant plus facile que la tête est bien fléchie.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 34 — Suites de couches pathologiques</em></p>","frequence":0},{"id":"31-3","rang":"A","rubrique":"Définition","titre":"Connaître les modifications de l’utérus liées à la grossesse et à l’accouchement","contenu":"<p>L’utérus subit des <span class=\"kw-def\">modifications majeures</span> pendant la <span class=\"kw-ci\">grossesse</span> pour devenir le moteur de l’accouchement.</p>\n\n      <h4>3 parties de l’utérus gravide</h4>\n\n      <ul>\n        <li><strong>Corps</strong> — forme d’ovoïde à grosse extrémité supérieure en fin de <span class=\"kw-ci\">grossesse</span></li>\n        <li><strong>Segment inférieur</strong> — portion <em>propre à la gravidité</em>, <span class=\"kw-alerte\">absent chez la femme non enceinte</span></li>\n        <li><strong>Col</strong> — contient 2 orifices : externe et interne</li>\n      </ul>\n\n      <h4>Segment inférieur (segment antérieur)</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Formation temporaire.</strong> N’apparaît qu’au <strong>3<sup>e</sup> trimestre</strong>, développé <strong>entre le corps et le col</strong> aux dépens de l’isthme utérin. En fin de travail : mesure <span class=\"kw-chiffre\">10 cm</span>, épaisseur de quelques millimètres seulement.\n        <ul>\n          <li><strong>Rôle :</strong> recueille la force de la contraction utérine et la dirige sur le col</li>\n          <li><strong>Peu vascularisé</strong> et limité en haut par la zone de décollement du péritoine vésico-utérin</li>\n          <li><strong>Intérêt chirurgical fondamental :</strong> <span class=\"kw-clinique\">zone d’incision des césariennes segmentaires transversales</span></li>\n        </ul>\n      </div>\n\n      <h4>3 tuniques de l’utérus</h4>\n\n      <table >\n        <thead>\n          <tr><th>Tunique</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Séreuse</strong></td>\n            <td>Péritoine, particularité = se clive facilement au niveau du segment inférieur</td>\n          </tr>\n          <tr>\n            <td><strong>Muqueuse</strong></td>\n            <td>Transformée en <span class=\"kw-clinique\">caduques</span> lors de la <span class=\"kw-ci\">grossesse</span></td>\n          </tr>\n          <tr>\n            <td><strong>Musculeuse (myomètre)</strong></td>\n            <td>\n              Fibres musculaires lisses disposées en 2 assises (externe + interne) de part et d’autre d’une <strong>couche plexiforme</strong> dont les faisceaux enserrent de nombreux vaisseaux.\n              <ul>\n                <li>Couche circulaire externe + faisceaux longitudinaux discontinus</li>\n                <li><span class=\"kw-alerte\">Phénomène des ligatures vivantes</span> = la rétraction des fibres efface la lumière des vaisseaux au niveau de la couche plexiforme → <strong>réduit l’hémorragie de la délivrance</strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Axe &amp; dextrorotation</h4>\n\n      <ul>\n        <li><strong>Axe du corps utérin :</strong> en décubitus, axe de poussée utérine légèrement incliné vers l’avant par rapport à l’axe du DS</li>\n        <li><strong>Dextrorotation :</strong> dans le plan frontal, l’utérus est fréquemment incliné <strong>du côté droit</strong> (rotation sur axe vertical, face antérieure dirigée en avant et à droite)</li>\n      </ul>\n\n      <h4>Modifications du col utérin</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Effacement puis dilatation.</strong>\n        <ul>\n          <li><strong>Effacement du col :</strong> disparition progressive de l’épaisseur et de la longueur du col</li>\n          <li><strong>Dilatation :</strong> orifice cervical s’élargit jusqu’à <span class=\"kw-chiffre\">10 cm</span> (dilatation complète)</li>\n          <li>Chez la <span class=\"kw-clinique\">multipare</span> : effacement et dilatation s’effectuent <strong>en même temps ⭐</strong></li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 34 — Suites de couches pathologiques</em></p>","frequence":0},{"id":"31-4","rang":"A","rubrique":"Définition","titre":"Connaître le rôle des contractions utérines et la manière de les surveiller","contenu":"<p>Les <span class=\"kw-def\">contractions utérines (CU)</span> sont le <strong>moteur de l’accouchement</strong>. Elles assurent la dilatation du col, la formation de la poche des eaux, et la progression du mobile fœtal.</p>\n\n      <h4>Caractéristiques des CU du travail</h4>\n\n      <ul>\n        <li><strong>Totales</strong> — intéressent tout l’utérus</li>\n        <li><strong>Involontaires</strong></li>\n        <li><strong>Intermittentes / répétées / rapprochées</strong> — chaque contraction précédée et suivie d’une période de repos</li>\n        <li><strong>Progressives</strong> dans leur durée, fréquence et intensité</li>\n        <li><strong>Douloureuses</strong> — <span class=\"kw-ttt\">analgésie péridurale</span> = moyen le plus efficace pour les supprimer</li>\n      </ul>\n\n      <h4>Rôles physiologiques des CU</h4>\n\n      <table >\n        <thead>\n          <tr><th>Cible</th><th>Effet</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Col utérin</strong></td>\n            <td>\n              <ol>\n                <li><strong>Effacement</strong> du col : disparition progressive de l’épaisseur et de la longueur</li>\n                <li><strong>Dilatation</strong> : élargissement progressif jusqu’à <span class=\"kw-chiffre\">10 cm</span></li>\n              </ol>\n              Chez la <span class=\"kw-clinique\">multipare</span> : effacement et dilatation simultanés ⭐\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Poche des eaux</strong></td>\n            <td>\n              Constitution par décollement des membranes au cours du travail. <strong>Double rôle :</strong>\n              <ul>\n                <li>Protecteur : œuf <span class=\"kw-bio\">vs</span> <strong>infection</strong>, fœtus <span class=\"kw-bio\">vs</span> <strong>traumatisme</strong></li>\n                <li>Mécanique : <strong>aide à la dilatation cervicale</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Mobile fœtal</strong></td>\n            <td>Permet le franchissement des étages de la filière pelvi-génitale (DS → excavation → DI → périnée)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-def\">Surveillance</span> des CU — Tocographie</h4>\n\n      <table >\n        <thead>\n          <tr><th>Méthode</th><th>Apport</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Tocographie externe</strong></td>\n            <td>Capteur externe → note la <strong>durée</strong> et la <strong>fréquence</strong> des CU</td>\n          </tr>\n          <tr>\n            <td><strong>Tocographie interne</strong></td>\n            <td>\n              Cathéter fin et souple introduit par voie transcervicale dans la cavité utérine →\n              <ul>\n                <li><strong>Tonus de base</strong></li>\n                <li><strong>Pression intra-utérine</strong></li>\n              </ul>\n              Peut être intra- ou extra-amniotique selon que les membranes sont rompues\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Cardiotocographie (CTG)</strong></td>\n            <td>Enregistrement <strong>simultané</strong> du <span class=\"kw-clinique\">RCF</span> + des CU — continu pendant les 2 premières étapes</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Anomalies des CU à reconnaître.</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Hypocinésie</span> — CU insuffisantes (fréquence/intensité)</li>\n          <li><span class=\"kw-alerte\">Hypercinésie</span> — CU excessives</li>\n          <li><span class=\"kw-alerte\">Hypotonie</span> — tonus de base trop bas</li>\n          <li><span class=\"kw-alerte\">Hypertonie</span> — tonus de base trop élevé (risque d’<strong><span class=\"kw-etio\">hypoxie fœtale</span></strong>)</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 24 — Complications de la <span class=\"kw-ci\">grossesse</span></em></p>","frequence":0},{"id":"31-5","rang":"A","rubrique":"Définition","titre":"Connaître les définitions des différents types d’accouchement","contenu":"<p>L’<span class=\"kw-def\">accouchement</span> = ensemble des phénomènes aboutissant à l’expulsion du fœtus et des annexes hors du ventre maternel (fœtus + placenta + liquide amniotique + membranes).</p>\n\n      <h4>Définitions fondamentales</h4>\n\n      <ul>\n        <li><strong>Accouchement normal</strong> = débute <span class=\"kw-clinique\">spontanément</span> (≠ déclenchement du travail)</li>\n        <li>Le fœtus doit franchir <strong>3 obstacles</strong> : <span class=\"kw-chiffre\">col utérin</span> + <span class=\"kw-chiffre\">bassin</span> + <span class=\"kw-chiffre\">périnée</span></li>\n        <li>Les <strong>contractions utérines</strong> sont le moteur de l’accouchement</li>\n      </ul>\n\n      <h4>Eutocique <span class=\"kw-bio\">vs</span> Dystocique</h4>\n\n      <table >\n        <thead>\n          <tr><th>Type</th><th>Définition</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Eutocique</strong></td>\n            <td>Expulsion par <strong>voie basse</strong> par la <em>seule influence des phénomènes naturels</em></td>\n          </tr>\n          <tr>\n            <td><strong>Dystocique</strong></td>\n            <td>Entraîne des <span class=\"kw-alerte\">difficultés ou impossibilités d’accouchement par voie basse</span> (nécessite manœuvres instrumentales ou césarienne)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Spontané <span class=\"kw-bio\">vs</span> Déclenché</h4>\n\n      <ul>\n        <li><strong>Accouchement spontané</strong> — travail démarre de lui-même</li>\n        <li><strong>Accouchement déclenché</strong> — induction du travail pour raison médicale (dépassement de terme, RPM, pathologie maternelle ou fœtale)</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Voies de naissance.</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">Voie basse</span> — accouchement vaginal (eutocique ou avec extraction instrumentale : forceps, ventouse, spatules)</li>\n          <li><span class=\"kw-clinique\">Voie haute</span> — <strong>césarienne</strong> (programmée ou en <span class=\"kw-alerte\">urgence</span>)</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 24 — Complications de la <span class=\"kw-ci\">grossesse</span></em></p>","frequence":0},{"id":"31-6","rang":"A","rubrique":"Définition","titre":"Connaître les différentes étapes de l’accouchement","contenu":"<p>L’accouchement se déroule en <span class=\"kw-def\">4 étapes</span> séquentielles. Connaître leur succession et leur durée est indispensable pour suivre la progression du travail.</p>\n\n      <h4>Vue d’ensemble — 4 étapes</h4>\n\n      <table >\n        <thead>\n          <tr><th>Étape</th><th>Début</th><th>Fin</th><th>Durée</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1<sup>re</sup> étape</strong><br><em>Dilatation du col</em></td>\n            <td>Début du vrai travail</td>\n            <td>Dilatation complète (<span class=\"kw-chiffre\">10 cm</span>)</td>\n            <td>\n              <ul>\n                <li>Primipare : <span class=\"kw-chiffre\">6–18 h</span></li>\n                <li>Multipare : <span class=\"kw-chiffre\">2–10 h</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2<sup>e</sup> étape</strong><br><em>Expulsion</em></td>\n            <td>Fin de la dilatation du col</td>\n            <td>Naissance de l’enfant</td>\n            <td><span class=\"kw-chiffre\">3–4 h maximum</span></td>\n          </tr>\n          <tr>\n            <td><strong>3<sup>e</sup> étape</strong><br><em>Délivrance</em></td>\n            <td>Naissance de l’enfant</td>\n            <td>Expulsion du placenta et des membranes</td>\n            <td><span class=\"kw-chiffre\">5–30 min</span></td>\n          </tr>\n          <tr>\n            <td><strong>4<sup>e</sup> étape</strong><br><em>Post-partum immédiat</em></td>\n            <td>Délivrance</td>\n            <td>Stabilisation des constantes maternelles</td>\n            <td><span class=\"kw-chiffre\">2 h</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Découpage du 1<sup>er</sup> <span class=\"kw-def\">stade</span></h4>\n\n      <ul>\n        <li><strong>Phase de latence</strong> — début du travail jusqu’à dilatation cervicale de <span class=\"kw-chiffre\">5–6 cm</span></li>\n        <li><strong>Phase active</strong> — de <span class=\"kw-chiffre\">5–6 cm</span> jusqu’à dilatation complète (<span class=\"kw-chiffre\">10 cm</span>)</li>\n      </ul>\n\n      <h4>Découpage du 2<sup>e</sup> <span class=\"kw-def\">stade</span></h4>\n\n      <ul>\n        <li><strong>Phase de descente</strong> (passive) — de la dilatation complète jusqu’au début des efforts expulsifs</li>\n        <li><strong>Phase d’expulsion</strong> (active) — entre le début des efforts expulsifs et la naissance</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Influence de la parité.</strong> La durée du travail est plus longue chez les <span class=\"kw-clinique\">nullipares</span> que chez les <span class=\"kw-clinique\">multipares</span>. Chez une même femme, la durée se raccourcit avec la parité. <span class=\"kw-alerte\">Grande multipare → risque d’accouchement à domicile</span> (travail très rapide).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-6 (description détaillée des étapes)</em></p>","frequence":0},{"id":"31-7","rang":"B","rubrique":"Définition","titre":"Connaître la description des différentes étapes du travail","contenu":"<p>La description détaillée du travail comporte <span class=\"kw-def\">3 stades</span> obstétricaux, avec des phases internes définissant la cinétique de la dilatation et de la descente fœtale.</p>\n\n      <h4>1<sup>er</sup> <span class=\"kw-def\">stade</span> — Dilatation du col</h4>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-def\">Diagnostic positif</span> du début du travail.</strong> Association de :\n        <ul>\n          <li><strong>Modifications du col :</strong> raccourcissement, ramollissement, ouverture jusqu’à dilatation complète (<span class=\"kw-chiffre\">10 cm</span>)</li>\n          <li><strong>CU du travail</strong> (par interrogatoire / palpation / tocographie) : totales, involontaires, intermittentes/répétées, progressives, douloureuses</li>\n        </ul>\n      </div>\n\n      <p><span class=\"kw-clinique\">Perte du « bouchon muqueux »</span> précède souvent le début du travail (écoulement de <strong>glaires épaisses et brunâtres</strong> par la vulve).</p>\n\n      <table >\n        <thead>\n          <tr><th>Phase</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Phase de latence</strong></td>\n            <td>\n              <ul>\n                <li>Dilatation jusqu’à <span class=\"kw-chiffre\">5–6 cm</span></li>\n                <li>Succède à l’effacement (parallèle chez la multipare ⭐)</li>\n                <li>Début du travail = <strong>&gt; 2 CU pour <span class=\"kw-chiffre\">10 min</span></strong></li>\n                <li>Phase <strong>la plus longue</strong> (parfois &gt; <span class=\"kw-chiffre\">10 h</span> chez la nullipare)</li>\n                <li><em>Ancien réf. :</em> moyenne <span class=\"kw-chiffre\">8,5 h</span> primipare / <span class=\"kw-chiffre\">5,5 h</span> multipare ; max <span class=\"kw-chiffre\">20 h</span> / <span class=\"kw-chiffre\">14 h</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Phase active</strong></td>\n            <td>\n              Après <span class=\"kw-chiffre\">5–6 cm</span>, vitesse de dilatation <span class=\"kw-alerte\">anormale</span> ⚠️ si :\n              <ul>\n                <li>Entre <span class=\"kw-chiffre\">5–7 cm</span> : <strong>&lt; <span class=\"kw-chiffre\">1 cm</span> / <span class=\"kw-chiffre\">4 h</span></strong></li>\n                <li>Entre <span class=\"kw-chiffre\">7 cm</span> et dilatation complète : <strong>&lt; <span class=\"kw-chiffre\">1 cm</span> / <span class=\"kw-chiffre\">2 h</span></strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Poche des eaux — types de <span class=\"kw-alerte\">rupture</span></h4>\n\n      <ul>\n        <li><strong>Spontanée</strong> — pendant le travail, sans intervention</li>\n        <li><strong>Artificielle (<span class=\"kw-ttt\">amniotomie</span>)</strong> — <span class=\"kw-alerte\">rupture</span> volontaire pour aider le travail (stagnation de la dilatation avec membranes intactes)</li>\n        <li><strong>Tempestive</strong> — à dilatation complète</li>\n        <li><strong>Intempestive</strong> — avant dilatation complète</li>\n        <li><span class=\"kw-alerte\"><strong>Prématurée (RPM)</strong></span> — <strong>avant tout travail</strong>, <strong>risque <span class=\"kw-etio\">infectieux</span> ⚠️</strong></li>\n      </ul>\n\n      <h4>2<sup>e</sup> <span class=\"kw-def\">stade</span> — Naissance</h4>\n\n      <ul>\n        <li><strong>Phase de descente (passive)</strong> — de la dilatation complète jusqu’au début des efforts expulsifs</li>\n        <li><strong>Phase d’expulsion (active)</strong> — du début des efforts expulsifs jusqu’à la naissance</li>\n      </ul>\n\n      <h4>3<sup>e</sup> <span class=\"kw-def\">stade</span> — Délivrance</h4>\n\n      <p>De la naissance de l’enfant jusqu’à l’expulsion du placenta. Durée normale : <span class=\"kw-chiffre\">5–30 min</span>. Au-delà de <span class=\"kw-alerte\">30 min</span> → délivrance artificielle.</p>\n\n      <h4><span class=\"kw-def\">Surveillance</span> — <span class=\"kw-ttt\">antibioprophylaxie</span> SGB</h4>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-ttt\">Antibioprophylaxie</span> SGB</strong> chez les femmes à risque (portage <span class=\"kw-etio\">Streptocoque B</span>) : <span class=\"kw-ttt\">pénicilline G</span>, <span class=\"kw-ttt\">amoxicilline</span>, <span class=\"kw-ttt\">ampicilline</span> ou <span class=\"kw-ttt\">céfazoline</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-5 (vue d’ensemble étapes) · obj-12 (délivrance)</em></p>","frequence":0},{"id":"31-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments de surveillance clinique de l’accouchement normal","contenu":"<p>La <span class=\"kw-def\">surveillance</span> clinique de l’accouchement repose sur un faisceau d’éléments cliniques et paracliniques reportés sur le <span class=\"kw-def\">partogramme</span>, au minimum <strong>toutes les heures</strong>.</p>\n\n      <h4>Examen clinique maternel</h4>\n\n      <table >\n        <thead>\n          <tr><th>Élément</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Analgésie</strong></td>\n            <td>Anesthésie péridurale possible en début de travail</td>\n          </tr>\n          <tr>\n            <td><strong>Abdomen</strong></td>\n            <td>Palpation = présentation fœtale (longitudinale/transversale) par recherche du pôle céphalique et du plan du dos</td>\n          </tr>\n          <tr>\n            <td><strong>Hauteur utérine</strong></td>\n            <td>Mesurée <strong>en dehors d’une CU</strong> — moyenne <span class=\"kw-chiffre\">33 cm</span></td>\n          </tr>\n          <tr>\n            <td><strong>Toucher vaginal (<span class=\"kw-alerte\">TV</span>)</strong></td>\n            <td>\n              Réalisé avec asepsie <strong>toutes les <span class=\"kw-chiffre\">30 min</span> à <span class=\"kw-chiffre\">1 h</span></strong>. Renseigne sur :\n              <ul>\n                <li>Diagnostic et variété de présentation</li>\n                <li>État de la poche des eaux (présence ou non de membranes)</li>\n                <li>État du col par <span class=\"kw-def\">score de Bishop</span> : <strong>dilatation · effacement · consistance · position du col · positionnement de la présentation fœtale</strong> (5 critères)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-def\">Score</span> de Bishop</h4>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-def\">Score</span> de Bishop</strong> — évalue la <strong>maturation du col</strong> en 5 critères côtés 0–2 ou 0–3 (sur 13). Détermine l’éligibilité au déclenchement du travail.\n      </div>\n\n      <h4>Poche des eaux &amp; liquide amniotique</h4>\n\n      <table >\n        <thead>\n          <tr><th>Situation</th><th>CAT</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Membranes intactes</strong></td>\n            <td>\n              <ul>\n                <li><strong>Conservation</strong> de l’intégrité de la poche des eaux, OU</li>\n                <li><strong><span class=\"kw-alerte\">Rupture</span> artificielle</strong> si <span class=\"kw-chiffre\">dilatation &gt; 6 cm</span> ET <strong>présentation engagée</strong></li>\n                <li>Après <span class=\"kw-alerte\">rupture</span> : <span class=\"kw-alerte\">réexaminer la parturiente pour vérifier l’absence de procidence du cordon</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>RPM</strong> (<span class=\"kw-alerte\">rupture</span> prématurée)</td>\n            <td>\n              Pas de poche des eaux. Risques :\n              <ul>\n                <li><span class=\"kw-alerte\">Infection</span></li>\n                <li><span class=\"kw-alerte\">Procidence du cordon</span> (cordon ombilical devant la présentation)</li>\n              </ul>\n              CAT : <strong><span class=\"kw-alerte\">hospitalisation</span> immédiate 🏥</strong>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Couleur du liquide amniotique</h4>\n\n      <ul>\n        <li><strong>Normale</strong> — clair, transparent, lactescent</li>\n        <li><strong>Épais ou teinté</strong> — en faveur d’une <span class=\"kw-etio\">chorioamniotite</span></li>\n        <li><strong>Vert ± sombre (méconial)</strong> — <span class=\"kw-alerte\">signe d’état fœtal non rassurant</span> (toute émission de méconium avant l’accouchement traduit une pathologie)</li>\n      </ul>\n\n      <h4><span class=\"kw-def\">Surveillance</span> fœtale</h4>\n\n      <ul>\n        <li><strong><span class=\"kw-imagerie\">Échographie</span></strong> en salle de travail : confirme l’examen obstétrical, estime la quantité de LA, localise le placenta, confirme la présentation</li>\n        <li><strong>Cardiotocographe (CTG)</strong> — enregistrement <strong>simultané</strong> :\n          <ul>\n            <li><span class=\"kw-clinique\">RCF</span> — <strong>continu pendant les 2 premières étapes</strong></li>\n            <li><span class=\"kw-clinique\">Tocographie</span> — caractéristiques des CU (anomalies = hypocinésie, hypercinésie, hypotonie, hypertonie)</li>\n          </ul>\n        </li>\n        <li><strong><span class=\"kw-bio\">ECG</span> fœtal</strong> ou <strong><span class=\"kw-bio\">pH au scalp</span></strong> — autres moyens de <span class=\"kw-def\">surveillance</span> fœtale</li>\n      </ul>\n\n      <h4><span class=\"kw-def\">Surveillance</span> du 4<sup>e</sup> <span class=\"kw-def\">stade</span></h4>\n\n      <div class=\"callout callout-warn\">\n        <strong>Post-partum immédiat — <span class=\"kw-chiffre\">2 h</span> en salle de travail.</strong>\n        <ul>\n          <li><span class=\"kw-def\">Surveillance</span> <strong>constante</strong> de l’accouchée pendant <span class=\"kw-chiffre\">2 h après la délivrance</span></li>\n          <li><strong>Expression utérine</strong> 2–3 fois : <em>empaumer l’utérus à pleine main et appuyer vers le bas</em> → évacue les caillots situés dans l’utérus et le vagin</li>\n        </ul>\n      </div>\n\n      <h4>Prévention de l’allo-immunisation Rh</h4>\n\n      <table >\n        <thead>\n          <tr><th>Situation</th><th>CAT</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Phénotype <span class=\"kw-ttt\">RhD</span> du nouveau-né non connu</strong></td>\n            <td>Contrôle du groupe Rh sur sang du cordon</td>\n          </tr>\n          <tr>\n            <td><strong>Mère Rh+ confirmé au <span class=\"kw-bio\">génotypage de grossesse</span></strong></td>\n            <td><span class=\"kw-clinique\">Aucun contrôle supplémentaire</span></td>\n          </tr>\n          <tr>\n            <td><strong>Mère Rh− + enfant Rh−</strong></td>\n            <td>Rien à faire après contrôle</td>\n          </tr>\n          <tr>\n            <td><strong>Mère Rh− + enfant Rh+</strong></td>\n            <td>\n              <ol>\n                <li><strong><span class=\"kw-bio\">Test de Kleihauer</span></strong> sur sang maternel <strong><span class=\"kw-chiffre\">≥ 30 min</span> après la délivrance</strong></li>\n                <li><strong>Prophylaxie anti-D</strong> chez la mère dans les <span class=\"kw-chiffre\">&lt; 72 h</span> (posologie ajustée au Kleihauer)</li>\n                <li>Injection possible <strong>jusqu’à <span class=\"kw-chiffre\">30 jours</span> après l’accouchement</strong> si oubli &lt; <span class=\"kw-chiffre\">72 h</span></li>\n              </ol>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 24 — Complications de la grossesse</em></p>","frequence":0},{"id":"31-9","rang":"B","rubrique":"Contenu multimédia","titre":"Engagement de la tête fœtale","contenu":"<p>L’<span class=\"kw-def\">engagement</span> = <strong>franchissement du DS par le plus grand <span class=\"kw-clinique\">diamètre</span> de la présentation</strong>. C’est le 1<sup>er</sup> temps de la traversée de la filière pelvienne et l’étape qui conditionne le plus souvent la possibilité d’accouchement par voie basse.</p>\n\n      <h4>Définition opérationnelle</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Présentation engagée</strong> = sa <strong>plus grande circonférence</strong> a franchi le DS. En présentation céphalique fléchie, cela correspond au passage du <span class=\"kw-clinique\">diamètre bipariétal de 9,5 cm</span>.\n      </div>\n\n      <h4>Accommodation de la tête fœtale au DS — 4 opérations</h4>\n\n      <ol>\n        <li><strong>Flexion du sommet</strong> — les dimensions les plus favorables sont <strong>sous-occipito-bregmatique + bipariétal</strong></li>\n        <li><strong>Orientation en oblique</strong> — les diamètres les plus utilisables du DS sont les <strong>diamètres obliques</strong></li>\n        <li><strong>Asynclitisme</strong> — inclinaison latérale (facultatif)</li>\n        <li><strong>Déformations plastiques</strong> — modelage de la tête (facultatif)</li>\n      </ol>\n\n      <h4>Forces en jeu (ancien référentiel)</h4>\n\n      <ul>\n        <li>Force de poussée (P) de la CU fait avec l’axe du DS un angle de <span class=\"kw-chiffre\">30–50°</span></li>\n        <li>P se décompose en :\n          <ul>\n            <li><strong>Force de progression (G)</strong> — perpendiculaire à l’axe du DS</li>\n            <li><strong>Force de résistance (R)</strong> — parallèle à l’axe, participe à la flexion et à l’orientation en oblique</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>Diagnostic clinique de l’engagement</h4>\n\n      <table >\n        <thead>\n          <tr><th>Type d’examen</th><th>Signes</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Symptômes maternels</strong></td>\n            <td>Femme respire plus librement (mobile descendu), mais gêne s’accentue du côté des organes pelviens</td>\n          </tr>\n          <tr>\n            <td><strong>Hauteur utérine</strong></td>\n            <td><strong>Diminué de quelques centimètres</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Palpation abdominale</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-clinique\">Signe de Le Lorier</span></strong> — engagée si <strong>2 doigts</strong> ne tiennent pas entre épaule antérieure du fœtus et bord supérieur du pubis</li>\n                <li><strong><span class=\"kw-clinique\">Signe de Favre</span></strong> — engagée si distance épaule antérieure ↔ bord supérieur du pubis &lt; <span class=\"kw-chiffre\">7 cm</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Toucher vaginal</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-clinique\">Signe de Farabeuf</span></strong> — engagée si <strong>2 doigts</strong> seulement entre pôle céphalique et plan sacro-coccygien</li>\n                <li><strong><span class=\"kw-clinique\">Signe de Demelin</span></strong> — engagée si index introduit perpendiculairement à la face antérieure de la SP, parallèlement à son bord inférieur, <strong>vient buter contre la présentation</strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Position par rapport aux épines sciatiques</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Référentiel des épines sciatiques.</strong>\n        <ul>\n          <li><span class=\"kw-chiffre\">Niveau 0</span> — sommet au niveau des épines = <strong>tête fœtale engagée</strong></li>\n          <li><span class=\"kw-chiffre\">Niveaux –1 à –5</span> — sommet <span class=\"kw-chiffre\">1 à 5 cm</span> <strong>au-dessus</strong> du plan des épines</li>\n          <li><span class=\"kw-chiffre\">Niveaux +1 à +5</span> — sommet <span class=\"kw-chiffre\">1 à 5 cm</span> <strong>en-dessous</strong> du plan des épines</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Schémas du KB sur la flexion céphalique et l’orientation oblique à intégrer manuellement. La compréhension visuelle est essentielle pour ce contenu multimédia — Kevin fournira les images.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-9 (orientation) · obj-1 (mobile fœtal)</em></p>","frequence":0},{"id":"31-10","rang":"B","rubrique":"Contenu multimédia","titre":"Orientation de la tête fœtale","contenu":"<p>L’<span class=\"kw-def\">orientation</span> = position d’engagement définie par l’orientation à <strong>gauche / droite</strong> et <strong>antérieure / postérieure</strong> du dos du fœtus (occiput = repère). Les diamètres obliques du DS sont les plus utilisables.</p>\n\n      <h4>Position d’engagement — variétés</h4>\n\n      <table >\n        <thead>\n          <tr><th>Variété</th><th>Sigle</th><th>Fréquence</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Occipito-iliaque gauche antérieure</td><td><strong>OIGA</strong> ⭐</td><td><span class=\"kw-chiffre\">57 %</span> — <strong>la plus fréquente d’engagement</strong></td></tr>\n          <tr><td>Occipito-iliaque droite postérieure</td><td><strong>OIDP</strong></td><td><span class=\"kw-chiffre\">33 %</span></td></tr>\n          <tr><td>Occipito-iliaque gauche postérieure</td><td>OIGP</td><td><span class=\"kw-chiffre\">6 %</span></td></tr>\n          <tr><td>Occipito-iliaque droite antérieure</td><td>OIDA</td><td><span class=\"kw-chiffre\">4 %</span></td></tr>\n          <tr><td>Occipito-iliaque gauche transverse</td><td>OIGT</td><td>variété accessoire</td></tr>\n          <tr><td>Occipito-iliaque droite transverse</td><td>OIDT</td><td>variété accessoire</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Ne pas confondre — Engagement <span class=\"kw-bio\">vs</span> Dégagement.</strong>\n        <ul>\n          <li>Présentation d’<strong>engagement</strong> : <span class=\"kw-clinique\">OIGA</span> (la plus fréquente)</li>\n          <li>Présentation de <strong>dégagement</strong> : <span class=\"kw-clinique\">OP</span> (occipito-pubienne, la plus fréquente)</li>\n        </ul>\n        📝 Piège classique en obstétrique — facile d’inverser engagement et dégagement.\n      </div>\n\n      <h4>Types de présentation et diamètres</h4>\n\n      <table >\n        <thead>\n          <tr><th>Présentation</th><th>Repère</th><th><span class=\"kw-clinique\">Diamètre</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Sommet</strong> (tête hyperfléchie)</td>\n            <td>Occiput</td>\n            <td>Bipariétal — <span class=\"kw-chiffre\">9,5 cm</span></td>\n          </tr>\n          <tr>\n            <td><strong>Face</strong> (tête totalement défléchie)</td>\n            <td>Menton</td>\n            <td>Sous-mento-bregmatique — <span class=\"kw-chiffre\">9,5 cm</span></td>\n          </tr>\n          <tr>\n            <td><strong>Front</strong> (flexion intermédiaire)</td>\n            <td>Nez</td>\n            <td>Syncipito-mentonnier — <span class=\"kw-alerte\">césarienne requise</span></td>\n          </tr>\n          <tr>\n            <td><strong>Bregma</strong> (flexion intermédiaire)</td>\n            <td>—</td>\n            <td>Occipito-frontal</td>\n          </tr>\n          <tr>\n            <td><strong>Siège</strong></td>\n            <td>Sacrum</td>\n            <td>Sacro-prétibial + bi-trochantérien</td>\n          </tr>\n          <tr>\n            <td><strong>Transversale (épaule)</strong></td>\n            <td>Acromion</td>\n            <td><span class=\"kw-alerte\">Césarienne requise</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Rotation dans l’excavation</h4>\n\n      <p>Les rotations tendent à ramener l’<strong>occiput en avant</strong> (OP) :</p>\n\n      <ul>\n        <li><strong>Variétés antérieures</strong> (OIGA, OIDA) → rotation de <span class=\"kw-chiffre\">45°</span> vers l’avant (OP)</li>\n        <li><strong><span class=\"kw-chiffre\">97 %</span> des variétés postérieures</strong> (OIDP, OIGP) → grande rotation de <span class=\"kw-chiffre\">135°</span> vers l’avant (OP)</li>\n        <li><strong><span class=\"kw-chiffre\">3 %</span> des variétés postérieures</strong> → rotation au plus court vers l’arrière en occipito-sacré (OS), <span class=\"kw-chiffre\">45°</span></li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Schémas du KB et collège de gynéco sur les variétés OIGA/OIDP, rotation 45°/135°, présentations céphaliques (sommet/face/front/bregma) à intégrer manuellement. Kevin fournira les images du collège.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-8 (engagement) · obj-1 (mobile fœtal)</em></p>","frequence":0},{"id":"31-11","rang":"B","rubrique":"Définition","titre":"Connaître les mécanismes périnéaux du dégagement de la tête fœtale","contenu":"<p>Le <span class=\"kw-def\">dégagement</span> commence quand la tête du fœtus est à la partie basse de l’excavation et se termine avec la naissance. Il se déroule en 3 étapes périnéales successives.</p>\n\n      <h4>3 étapes du dégagement céphalique</h4>\n\n      <table >\n        <thead>\n          <tr><th>Étape</th><th>Phénomènes périnéaux</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1. Distension du périnée postérieur</strong></td>\n            <td>\n              <ul>\n                <li><strong>Hyperflexion de la tête</strong> accentue la descente</li>\n                <li><strong>Rétropulsion du coccyx</strong> → agrandit le <span class=\"kw-clinique\">diamètre</span> antéro-postérieur du DI de <span class=\"kw-chiffre\">9 à 11 cm</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2. Distension du périnée antérieur</strong></td>\n            <td>\n              <ul>\n                <li><strong>Noyau fibreux du périnée</strong> abordé de front, refoulé par la présentation qui s’en coiffe</li>\n                <li>Laminage et distension en tous sens</li>\n                <li><strong>Distance ano-vulvaire triple ou quadruple</strong></li>\n                <li>La vulve s’oriente directement « en avant »</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>3. Dégagement de la présentation</strong></td>\n            <td>\n              <strong>Soit dégagement occipito-pubien (OP)</strong> — le plus fréquent (occiput s’appuie sur la SP)\n              <ol>\n                <li>Partie sous-occipitale se fixe sous la symphyse → point de rotation pour la <strong>déflexion</strong></li>\n                <li>Opérateur contrôle l’expulsion (main sur le sommet de la tête)</li>\n                <li>Déflexion progressive : <strong>bosses frontales → yeux → nez → bouche → menton</strong></li>\n                <li>Épisiotomie <strong>parfois nécessaire</strong>, <span class=\"kw-clinique\">non systématique</span></li>\n              </ol>\n              <strong>Soit dégagement occipito-sacré (OS)</strong> — rare (occiput s’appuie contre le sacrum)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Asynclitisme et déformations plastiques</h4>\n\n      <ul>\n        <li><strong>Asynclitisme</strong> — inclinaison latérale facultative du sommet pour faciliter le passage</li>\n        <li><strong>Déformations plastiques</strong> — modelage des os du crâne fœtal grâce aux sutures et fontanelles (bosse séro-sanguine possible)</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Rôle de l’opérateur.</strong> Contrôle de la sortie par une main sur le sommet pour <strong>éviter une expulsion brutale</strong> (déchirures périnéales). Épisiotomie discutée au cas par cas.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-11 (techniques de poussée et dégagement) · obj-7 (<span class=\"kw-def\">surveillance</span>)</em></p>","frequence":0},{"id":"31-12","rang":"B","rubrique":"Prise en charge","titre":"Connaître les techniques de poussée et de dégagement","contenu":"<p>Les <span class=\"kw-def\">techniques de poussée</span> sont à connaître pour accompagner efficacement la 2<sup>e</sup> étape du travail. La poussée doit être <strong>synchrone des CU</strong>, et les efforts expulsifs ne doivent pas excéder <span class=\"kw-alerte\">30 minutes</span>.</p>\n\n      <h4>Conditions préalables à l’expulsion</h4>\n\n      <ul>\n        <li><span class=\"kw-def\">Surveillance</span> cardiotocographique <strong>maintenue en continu</strong></li>\n        <li><strong>Vessie vidée</strong> préalablement</li>\n        <li>Installation en <strong>position demi-assise</strong> si expulsion imminente</li>\n      </ul>\n\n      <h4>Physiologie de la poussée</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Réflexe de poussée.</strong> L’envie de pousser est déterminée par le <strong>contact de la présentation avec le plancher pelvi-périnéal</strong>. Les efforts expulsifs <strong>volontaires</strong> doivent être <strong>concomitants des CU</strong> pour assurer une bonne descente du mobile fœtal.\n      </div>\n\n      <h4>Technique en inspiration bloquée (Valsalva)</h4>\n\n      <ol>\n        <li><strong>Inspirer</strong> → souffler → inspirer</li>\n        <li><strong>Bloquer la respiration</strong></li>\n        <li><strong>Pousser vers le bas</strong> pendant toute la durée de la CU</li>\n        <li>Patiente <strong>se repose</strong> entre chaque CU (respiration ample et profonde)</li>\n        <li>Patiente <strong>arrête de pousser</strong> lorsque l’opérateur intervient (respiration lente et profonde) — <span class=\"kw-alerte\">éviter une expulsion brusque qui risquerait d’entraîner des déchirures</span></li>\n      </ol>\n\n      <p><em>Technique de la <strong>poussée en expiration</strong> également possible (alternative à Valsalva).</em></p>\n\n      <h4>Dégagement du reste du corps</h4>\n\n      <table >\n        <thead>\n          <tr><th>Temps</th><th>Manœuvre</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1. Sortie de la tête — vérification du cordon</strong></td>\n            <td>\n              Vérifier l’<strong>absence de circulaire du cordon</strong> (anomalie : enroulement autour du cou).\n              <ul>\n                <li><strong>Circulaire lâche :</strong> faire glisser autour du thorax fœtal</li>\n                <li><strong>Circulaire serré :</strong> <span class=\"kw-alerte\">couper entre 2 pinces Kocher</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2. Rotation de restitution</strong></td>\n            <td>L’opérateur accentue la rotation spontanée — amène l’occiput fœtal à proximité de l’anus maternel (en OS) → permet aux épaules de passer du <span class=\"kw-clinique\">diamètre</span> oblique du DS au diamètre antéro-postérieur du DI</td>\n          </tr>\n          <tr>\n            <td><strong>3. Dégagement des épaules</strong></td>\n            <td>\n              Traction douce vers le bas dans l’axe ombilico-coccygien :\n              <ul>\n                <li>Épaule <strong>antérieure</strong> puis <strong>postérieure</strong></li>\n                <li>Passage du <strong><span class=\"kw-clinique\">diamètre</span> bi-acromial</strong></li>\n                <li><span class=\"kw-alerte\">Temps d’extraction des épaules ne doit pas dépasser &lt; 40 secondes</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>4. Expulsion du siège</strong></td>\n            <td>Suit sans difficulté (<span class=\"kw-clinique\">diamètre</span> bitrochantérien = <span class=\"kw-chiffre\">9 cm</span> seulement)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Après expulsion — clampage du cordon</h4>\n\n      <ul>\n        <li>Enfant posé <strong>sur le ventre de sa mère</strong>, tête en position déclive</li>\n        <li><strong>Clampage précoce</strong> — dès les premières secondes</li>\n        <li><span class=\"kw-clinique\"><strong>Clampage retardé (recommandé)</strong></span> — pendant <strong>&gt; 30 secondes jusqu’à <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> min</span>utes</strong> avant le coupage → permet au bébé de bénéficier du transfert du sang du placenta (nutriments + cellules souches)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-10 (mécanismes périnéaux) · obj-7 (<span class=\"kw-def\">surveillance</span>)</em></p>","frequence":0},{"id":"31-13","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les différents temps de la délivrance","contenu":"<p>La <span class=\"kw-def\">délivrance</span> = ensemble des phénomènes physiologiques aboutissant à l’expulsion du placenta et des membranes. Elle <strong>termine l’accouchement</strong> et se déroule en <strong>3 temps</strong>.</p>\n\n      <h4>3 temps de la délivrance</h4>\n\n      <table >\n        <thead>\n          <tr><th>Temps</th><th>Mécanisme</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1. Décollement placentaire</strong></td>\n            <td>\n              <ol>\n                <li><strong>Rétraction utérine</strong> dès la sortie de l’enfant → <span class=\"kw-ttt\">réduction</span> de la surface d’insertion placentaire (villosités crampons tirent sur la muqueuse, amorçant le clivage et déchirant les sinus veineux)</li>\n                <li><strong>Intensification des CU</strong> après expulsion du fœtus → clivage (= cause essentielle ; fond utérin remonte au-dessus de l’ombilic)</li>\n                <li><strong>Hématome rétro-placentaire physiologique</strong> → complète la séparation</li>\n              </ol>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2. Expulsion du placenta</strong></td>\n            <td>\n              Mécanisme principal : <strong>contractions utérines</strong>. Plus accessoirement : efforts expulsifs, poids du placenta, hématome inter-utéro-placentaire.<br>\n              <strong>Manœuvre douce :</strong>\n              <ul>\n                <li>1 main empaume le fond utérin pour abaisser le placenta fermement vers le bas</li>\n                <li>1 main maintient le cordon <strong>tendu sans traction</strong></li>\n              </ul>\n              <span class=\"kw-alerte\">⚠️ Ne pas tirer sur le cordon, ne pas exécuter de manœuvres hâtives</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>3. Hémostase</strong></td>\n            <td>\n              Assurée par :\n              <ul>\n                <li><strong>Thrombose des vaisseaux</strong> (facteurs de la coagulation)</li>\n                <li><strong>Rétraction utérine</strong> = phénomène des <span class=\"kw-def\">ligatures vivantes</span> (faisceaux musculaires de la couche plexiforme enserrent et obturent les vaisseaux)</li>\n              </ul>\n              <em>Mécanisme efficace uniquement après évacuation totale de la cavité utérine.</em>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Reconnaissance clinique du décollement placentaire</h4>\n\n      <ul>\n        <li><strong>Métrorragie</strong></li>\n        <li><strong>Déroulement du cordon</strong> hors de la vulve (pince témoin objective la descente)</li>\n        <li>Pression sus-pubienne / mobilisation utérine vers le haut <strong>ne fait pas remonter le cordon</strong> = <span class=\"kw-clinique\">signe d’affirmation du décollement</span></li>\n        <li>Redescente du fond utérin après ascension momentanée</li>\n        <li><span class=\"kw-alerte\">TV</span> susceptible d’affirmer la présence du placenta dans le vagin</li>\n      </ul>\n\n      <h4>Examen du placenta</h4>\n\n      <ul>\n        <li>Présentation à l’orifice vulvaire :\n          <ul>\n            <li><strong>Face fœtale</strong> — le plus souvent (mode <span class=\"kw-clinique\">Baudelocque</span>)</li>\n            <li><strong>Face maternelle ou bord</strong> — parfois (mode Duncan)</li>\n          </ul>\n        </li>\n        <li><strong>Sac membraneux :</strong> inspecté par transparence à la recherche d’une <span class=\"kw-alerte\">zone dépolie/granuleuse où arrivent des vaisseaux</span> = <strong>cotylédon aberrant</strong> (insertion sur les membranes à distance de la <span class=\"kw-clinique\">masse</span> placentaire)</li>\n        <li><strong>Face fœtale :</strong> noter le lieu d’insertion du cordon, contrôler la présence de <span class=\"kw-chiffre\">2 artères + 1 veine</span> funiculaires</li>\n        <li><strong>Face maternelle :</strong> débarrassée des caillots, cotylédons doivent se juxtaposer sans solution de continuité</li>\n      </ul>\n\n      <h4>Délivrance dirigée</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Délivrance dirigée — prévention HPP.</strong>\n        <ul>\n          <li><strong>Objectif :</strong> prévention de l’hémorragie de la délivrance</li>\n          <li><strong>Principe :</strong> administration préventive d’<span class=\"kw-ttt\">oxytocine IV 5–10 UI</span> (utérotonique)</li>\n          <li><strong>Quand ?</strong> idéalement <strong>au moment du dégagement des épaules</strong>, ou rapidement après la naissance</li>\n        </ul>\n      </div>\n\n      <h4><span class=\"kw-ttt\">Délivrance artificielle</span> &amp; révision utérine</h4>\n\n      <table >\n        <thead>\n          <tr><th>Geste</th><th>Indication</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Délivrance artificielle</span></strong></td>\n            <td>Patiente <span class=\"kw-alerte\">non délivrée après 30 minutes</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Révision utérine</span></strong></td>\n            <td>\n              <ul>\n                <li>Placenta incomplet (cotylédon manquant, absence du sac membraneux)</li>\n                <li><span class=\"kw-alerte\">Hémorragie du post-partum immédiat</span> (volume de sang perdu <span class=\"kw-chiffre\">≥ 500 cm³</span>)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Après l’hémostase — globe de sécurité.</strong>\n        <ul>\n          <li>Femme <strong>soulagée, détendue, FC/PA normales</strong></li>\n          <li>Utérus diminue de taille → <span class=\"kw-clinique\">masse</span> <strong>dure et arrondie</strong> en région sus-pubienne = <span class=\"kw-clinique\">globe de sécurité</span></li>\n        </ul>\n        Absence de globe de sécurité = <span class=\"kw-etio\">atonie utérine</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 24 — Complications de la <span class=\"kw-ci\">grossesse</span> · 34 — Suites de couches pathologiques · 332 — États de <span class=\"kw-alerte\">choc</span> (HPP)</em></p>","frequence":0},{"id":"31-14","rang":"A","rubrique":"Physiopathologie","titre":"Connaître les suites de couche normales","contenu":"<p>Les <span class=\"kw-def\">suites de couches</span> = période d’<strong>environ <span class=\"kw-chiffre\">6 semaines</span> (<span class=\"kw-chiffre\">40 jours</span>)</strong> qui débute <strong><span class=\"kw-chiffre\">2 h</span> après l’accouchement</strong> et se termine par le <strong>retour de couches</strong> (retour des menstruations).</p>\n\n      <h4>Éléments cliniques de <span class=\"kw-def\">surveillance</span></h4>\n\n      <ul>\n        <li><strong>Signes généraux</strong> — pouls, PA, température, état général, douleur</li>\n        <li><strong>Seins</strong> — tension, douleur, crevasses</li>\n        <li><strong>Involution du globe utérin</strong> — hauteur et consistance de l’utérus</li>\n        <li><strong>Cicatrisation périnéale</strong></li>\n        <li><strong>Lochies</strong> (écoulement vaginal sanglant du post-partum) — abondance, aspect, odeur</li>\n        <li><strong>Membres inférieurs</strong> — recherche de signes de phlébite</li>\n        <li><strong>Appareil urinaire</strong> — signes fonctionnels, aspect des urines</li>\n        <li><strong>Si césarienne</strong> — cicatrice, douleur, reprise du transit, mictions et couleur des urines</li>\n      </ul>\n\n      <p><span class=\"kw-alerte\">Hospitalisation</span> possible jusqu’au <span class=\"kw-chiffre\">12<sup>e</sup> jour</span> pour la sécurité sociale.</p>\n\n      <h4>Involution utérine</h4>\n\n      <table >\n        <thead>\n          <tr><th>Élément</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Mécanisme</strong></td>\n            <td>Diminution du volume + réintégration de l’utérus dans la cavité pelvienne (sous l’influence de <strong>CU infracliniques</strong>, <span class=\"kw-clinique\">douloureuses chez la multipare</span> = « <span class=\"kw-clinique\">tranchées</span> »)</td>\n          </tr>\n          <tr>\n            <td><strong>Facteurs favorisants</strong></td>\n            <td>\n              <ul>\n                <li>Prescription d’<span class=\"kw-ttt\">ocytociques</span> (favorisent les CU et donc l’involution)</li>\n                <li><span class=\"kw-ci\">Allaitement</span> maternel (la succion du nouveau-né stimule la libération d’ocytocine)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span></strong></td>\n            <td>\n              <ul>\n                <li>Utérus gros/globuleux pendant <span class=\"kw-chiffre\">15 jours</span> → retrouve sa taille normale en <span class=\"kw-chiffre\">2–3 mois</span></li>\n                <li>Reconstitution du col utérin :\n                  <ul>\n                    <li>Col prend de la longueur et de la consistance</li>\n                    <li>Fermeture de l’orifice interne : vers le <span class=\"kw-chiffre\">10<sup>e</sup> jour</span></li>\n                    <li>Fermeture de l’orifice externe : vers le <span class=\"kw-chiffre\">15–20<sup>e</sup> jour</span></li>\n                    <li>Disparition du segment inférieur : en quelques jours</li>\n                  </ul>\n                </li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Lochies</h4>\n\n      <ul>\n        <li><strong>4 premiers jours :</strong> écoulement sérosanguinolent/sanglant physiologique</li>\n        <li><strong>Éclaircissement progressif :</strong> lochies <strong>totalement claires vers J10</strong></li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Globe de sécurité.</strong> L’utérus doit conserver le classique <span class=\"kw-clinique\">globe de sécurité</span> (utérus rétracté et tonique) lors du séjour en maternité.\n        <ul>\n          <li>Contrôle <strong>journalier</strong> de l’involution utérine</li>\n          <li>Pathologies où l’utérus est mal involué : <span class=\"kw-etio\">atonie utérine</span>, <span class=\"kw-etio\">endométrite du post-partum</span></li>\n        </ul>\n      </div>\n\n      <h4>Retour de couches &amp; ovulation</h4>\n\n      <table >\n        <thead>\n          <tr><th>Élément</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Reconstitution endomètre (3 phases)</strong></td>\n            <td>\n              <ul>\n                <li>Régression : <span class=\"kw-chiffre\">4–5 jours</span> (dégénérescence de la caduque)</li>\n                <li>Cicatrisation : jusqu’au 25<sup>e</sup> jour</li>\n                <li>Prolifération : 25–45<sup>e</sup> jour</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Sans <span class=\"kw-ci\">allaitement</span></strong></td>\n            <td>Retour de couches vers le <span class=\"kw-chiffre\">45<sup>e</sup> jour</span> post-partum (<span class=\"kw-chiffre\">6–12 semaines</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Avec <span class=\"kw-ci\">allaitement</span> maternel</strong></td>\n            <td>Retour en <span class=\"kw-chiffre\">4–6 mois</span> (≈ <span class=\"kw-chiffre\">40 jours</span> après la fin de l’<span class=\"kw-ci\">allaitement</span>) — endomètre garde un aspect régressif de repos</td>\n          </tr>\n          <tr>\n            <td><strong>Petit retour de couches</strong></td>\n            <td>Hémorragie de faible abondance vers le <strong>20<sup>e</sup> jour</strong> pendant <span class=\"kw-chiffre\">2–3 jours</span></td>\n          </tr>\n          <tr>\n            <td><strong>Ovulation</strong></td>\n            <td>\n              <span class=\"kw-alerte\">1<sup>er</sup> cycle peut être ovulatoire dans 5–10 % des cas</span><br>\n              <strong>L’<span class=\"kw-ci\">allaitement</span> maternel n’est pas une contraception garantie</strong> ⚠️\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Sécrétion lactée</h4>\n\n      <table >\n        <thead>\n          <tr><th>Hormone</th><th>Rôle</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Prolactine</span></strong></td>\n            <td>Conditionne la <strong>synthèse + stockage/sécrétion</strong> du lait par les lactocytes (galactopoïèse)</td>\n          </tr>\n          <tr>\n            <td><strong>Ocytocine</strong></td>\n            <td>Favorise l’<strong>éjection du lait</strong> en stimulant la contraction des cellules myo-épithéliales autour des lactocytes</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Montée laiteuse</strong> — survient au <span class=\"kw-chiffre\">2–3<sup>e</sup> jour</span> du post-partum (= 2<sup>e</sup> phase de la lactogenèse) :\n        <ul>\n          <li>Seins gonflent, tendus et sensibles, <strong>fébricule transitoire possible à <span class=\"kw-chiffre\">38 °C</span></strong></li>\n          <li>Liée à l’asynchronisme entre lactogenèse et mécanismes d’éjection du lait</li>\n          <li>Normalisation par tétées fréquentes et efficaces</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-14 (PEC post-partum immédiat) · obj-15 (contraception) · 34 — Suites de couches pathologiques · 69 — Troubles psychiques de la <span class=\"kw-ci\">grossesse</span> et du post-partum</em></p>","frequence":0},{"id":"31-15","rang":"A","rubrique":"Prise en charge","titre":"Savoir prendre en charge une accouchée dans le post-partum immédiat","contenu":"<p>La prise en charge du <span class=\"kw-def\">post-partum immédiat</span> vise 5 objectifs structurants pendant le séjour en maternité.</p>\n\n      <h4>5 objectifs du séjour en maternité</h4>\n\n      <ul>\n        <li><strong>Favoriser et contrôler</strong> la bonne involution de l’utérus + s’assurer de l’absence d’hémorragie</li>\n        <li><strong>Contrôler l’<span class=\"kw-ci\">allaitement</span></strong></li>\n        <li><strong>Prévenir et dépister</strong> les infections locales et générales + les accidents thromboemboliques</li>\n        <li><strong>Soins du périnée</strong> — toilettes fréquentes, éviter la macération, information sur la rééducation pelvi-périnéale</li>\n        <li><strong>Information médicale + actions de prévention</strong></li>\n      </ul>\n\n      <h4><span class=\"kw-ci\">Allaitement</span> maternel — bonnes pratiques</h4>\n\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Recommandation</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1<sup>re</sup> tétée</strong></td>\n            <td>Mise au sein <strong>immédiate</strong>, si possible en salle de travail (sans précipitation, <span class=\"kw-chiffre\">&lt; 30 min</span> après la naissance) — le colostrum est très riche en Ig, et le réflexe de succion est à son maximum</td>\n          </tr>\n          <tr>\n            <td><strong>Installation</strong></td>\n            <td>\n              <ul>\n                <li>Mère assise ou couchée, donner les <strong>2 seins à chaque tétée</strong> (alterner = diminue les complications)</li>\n                <li>Bouche du nouveau-né doit prendre <strong>largement l’aréole</strong> (pas seulement le mamelon)</li>\n                <li>Menton et nez contre le sein, tête légèrement inclinée en arrière</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Horaires</strong></td>\n            <td>\n              <span class=\"kw-ci\">Allaitement</span> <strong>souple à la demande</strong>. Fréquence moyenne : <span class=\"kw-chiffre\">1 tétée toutes les 2–3 h au début</span>, puis espacement progressif guidé par le nouveau-né.\n              <ul>\n                <li>Signes : regard/comportement (mouvements yeux, lèvres, tête, main à la bouche)</li>\n                <li>Ne pas attendre l’agitation ou les pleurs</li>\n                <li>Ne pas juger seulement sur la courbe de poids</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Durée</strong></td>\n            <td>Variable selon l’enfant — très courte (efficace, actif) à plus longue (prématurés, lent, tétouille)</td>\n          </tr>\n          <tr>\n            <td><strong>Signes d’<span class=\"kw-ci\">allaitement</span> efficace</strong></td>\n            <td>\n              <ul>\n                <li><strong>Tétées</strong> —<span class=\"kw-chiffre\"> 8–12/jour</span> de façon efficace (y compris la nuit pendant les 1<sup>ers</sup> mois)</li>\n                <li><strong>Selles</strong> — &gt;<span class=\"kw-chiffre\"> 3/jour</span> molles, grumeleuses, jaunes</li>\n                <li><strong>Urines</strong> — 5–6 couches mouillées et lourdes/jour (diurèse satisfaisante)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Conseils à favoriser ✅</h4>\n\n      <ul>\n        <li>Laisser l’enfant avec sa mère <strong><span class=\"kw-chiffre\">24 h</span> sur 24</strong></li>\n        <li>Lavage quotidien des seins à l’eau et au savon</li>\n        <li>Protection des mamelons avec compresse sèche (éviter macération)</li>\n        <li>Encourager les associations de soutien à l’<span class=\"kw-ci\">allaitement</span> maternel</li>\n        <li>Boissons abondantes, alimentation variée et riche en protéines et calcium</li>\n      </ul>\n\n      <h4>À éviter ❌</h4>\n\n      <ul>\n        <li><strong>Proscription du <span class=\"kw-etio\">tabac</span>, <span class=\"kw-etio\">alcool</span>, excitants</strong> (café, thé)</li>\n        <li><strong>Pas de tétine artificielle ou sucette</strong> chez l’enfant allaité</li>\n        <li>Éviter les crèmes cosmétiques sur les seins ; <strong>pas d’antisepsie nécessaire</strong></li>\n        <li>Aucun médicament ou régime alimentaire censé augmenter la sécrétion lactée</li>\n        <li>Production de lait diminue si ajout de biberons (moins de stimulation)</li>\n      </ul>\n\n      <h4>Prévention de la maladie thromboembolique veineuse (MTEV)</h4>\n\n      <table >\n        <thead>\n          <tr><th>Niveau de risque</th><th>Facteurs</th><th>Prophylaxie</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Risque majeur</strong></td>\n            <td>\n              <ul>\n                <li>ATCD de <strong>MTEV multiples</strong></li>\n                <li><strong>Thrombophilie</strong> traitée au long cours par <span class=\"kw-ttt\">anticoagulant</span></li>\n              </ul>\n            </td>\n            <td>Bas de contention + <strong><span class=\"kw-ttt\">AVK</span></strong> pendant <span class=\"kw-chiffre\">≥ 3 mois</span></td>\n          </tr>\n          <tr>\n            <td><strong>Risque élevé</strong></td>\n            <td>\n              <ul>\n                <li>ATCD MTEV sans FR retrouvé</li>\n                <li>ATCD MTEV en contexte de <span class=\"kw-ci\">grossesse</span> ou de traitement œstrogénique</li>\n                <li>ATCD MTEV + facteur <span class=\"kw-ttt\">biologique</span> (déficit AT, SAPL, mutation 20210A homozygote, <span class=\"kw-etio\">FV Leiden</span> homozygote, anomalies hétérozygotes combinées)</li>\n              </ul>\n            </td>\n            <td>Bas de contention + <strong><span class=\"kw-ttt\">HBPM à dose prophylactique forte</span></strong> (<span class=\"kw-ttt\">énoxaparine</span> 4 <span class=\"kw-chiffre\">000 UI</span>/j ou <span class=\"kw-ttt\">daltéparine</span> 5 <span class=\"kw-chiffre\">000 UI</span>/j) pendant <span class=\"kw-chiffre\">6–8 semaines</span></td>\n          </tr>\n          <tr>\n            <td><strong>Risque modéré</strong></td>\n            <td>\n              <ul>\n                <li>ATCD MTEV avec facteur déclenchant temporaire</li>\n                <li>ATCD MTEV + autre facteur <span class=\"kw-ttt\">biologique</span></li>\n                <li>Facteur <span class=\"kw-ttt\">biologique</span> asymptomatique dépisté dans une MTEV familiale</li>\n                <li><strong>Césarienne en <span class=\"kw-alerte\">urgence</span></strong></li>\n                <li>Césarienne + <span class=\"kw-ttt\">chirurgie</span> pelvienne majeure associée</li>\n                <li>Présence de <span class=\"kw-chiffre\">≥ 3</span> FR faibles</li>\n              </ul>\n            </td>\n            <td>Bas de contention + <strong><span class=\"kw-ttt\">HBPM à dose prophylactique forte</span></strong> pendant <span class=\"kw-chiffre\">6–8 semaines</span> (dose et durée modulables)</td>\n          </tr>\n          <tr>\n            <td><strong>Risque faible</strong></td>\n            <td>\n              Si &lt; 3 FR suivants : âge &gt;<span class=\"kw-chiffre\"> 35 ans</span>, <span class=\"kw-etio\">obésité</span> (IMC &gt; 30 ou poids &gt;<span class=\"kw-chiffre\"> 80 kg</span>), varices, <span class=\"kw-def\">HTA</span>, césarienne, multiparité &gt; 4, <span class=\"kw-etio\">prééclampsie</span>, alitement strict prolongé, HPP, <span class=\"kw-def\">syndrome néphrotique</span>, <span class=\"kw-def\">MICI</span> en poussée, infection systémique\n            </td>\n            <td>Bas de contention seuls — <span class=\"kw-clinique\">pas d’anticoagulant</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj-13 (suites de couches) · obj-15 (contraception PP) · 34 — Suites de couches pathologiques · 226 — <span class=\"kw-def\">TVP</span> / EP · 69 — Troubles psychiques de la <span class=\"kw-ci\">grossesse</span> et du PP</em></p>","frequence":0},{"id":"31-16","rang":"B","rubrique":"Prise en charge","titre":"Savoir prescrire une contraception du post partum","contenu":"<p>La <span class=\"kw-def\">contraception du post-partum</span> est <strong>provisoire</strong> et devra être rediscutée à la visite postnatale. Sa précocité de mise en place est cruciale : la reprise de la fertilité est précoce (mais pas avant <span class=\"kw-chiffre\">25 jours</span>).</p>\n\n      <h4>Généralités</h4>\n\n      <table >\n        <thead>\n          <tr><th>Élément</th><th>Donnée clé</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Reprise des rapports</strong></td>\n            <td>En moyenne <span class=\"kw-chiffre\">5 semaines</span> après l’accouchement — à <span class=\"kw-chiffre\">1 mois</span>, ≈ <span class=\"kw-chiffre\">60 %</span> des couples ont eu <span class=\"kw-chiffre\">≥ 1</span> rapport</td>\n          </tr>\n          <tr>\n            <td><strong>IVG post-PP</strong></td>\n            <td><span class=\"kw-alerte\">5,5 % des IVG en France</span> surviennent dans les <span class=\"kw-chiffre\">6 mois</span> après un accouchement (≈ 11 000 femmes/an)</td>\n          </tr>\n          <tr>\n            <td><strong>Reprise de la fertilité</strong></td>\n            <td>Précoce, mais <strong>pas avant <span class=\"kw-chiffre\">25 jours</span></strong> → <span class=\"kw-clinique\">débuter la contraception vers le 21<sup>e</sup> jour</span></td>\n          </tr>\n          <tr>\n            <td><strong>Visite postnatale</strong></td>\n            <td><span class=\"kw-chiffre\">30 %</span> des femmes n’ont pas repris ou ont abandonné leur contraception → méthode prescrite souvent non adaptée à toutes</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Quand reprendre l’activité sexuelle ?</h4>\n\n      <p>Dès que le <strong>périnée est confortable et guéri</strong> et que le <strong>sang rouge clair a disparu</strong> : <span class=\"kw-chiffre\">2–3 semaines</span>.</p>\n\n      <h4>Méthodes contraceptives — post-partum</h4>\n\n      <table >\n        <thead>\n          <tr><th>Méthode</th><th>Modalités en post-partum</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Méthodes barrières</strong> ✅</td>\n            <td>\n              Préservatifs, spermicides (crèmes, ovules, éponges).<br>\n              <span class=\"kw-alerte\">Diaphragme plus difficile à utiliser en post-partum ❌</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>DIU (stérilet)</strong></td>\n            <td>\n              <strong>Avantages :</strong>\n              <ul>\n                <li>Pose sans danger (risque infection/perforation non augmenté)</li>\n                <li>Méthode idéale chez la femme qui allaite (aucun effet sur la qualité/composition du lait)</li>\n              </ul>\n              <strong>Inconvénient principal :</strong>\n              <ul>\n                <li><span class=\"kw-alerte\">Taux élevé d’expulsion</span> à cause des CU et de la dilatation cervicale (<span class=\"kw-chiffre\">12–40 %</span> expulsés à <span class=\"kw-chiffre\">6 mois</span>)</li>\n                <li><strong>Prévention :</strong> pose idéalement après <span class=\"kw-chiffre\">≥ 3 mois</span> (après retour de couches ou en fin d’involution utérine)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Œstro-progestatifs (COP)</strong> ❌</td>\n            <td>\n              <strong>Ne pas prescrire avant le 3<sup>e</sup> mois</strong> après un accouchement :\n              <ul>\n                <li><span class=\"kw-alerte\">Risque thrombotique majoré</span> (pendant <span class=\"kw-ci\">grossesse</span> + post-partum pendant <span class=\"kw-chiffre\">≥ 6–9 semaines</span>)</li>\n                <li><span class=\"kw-alerte\">Risque d’ablactation</span> avant <span class=\"kw-chiffre\">6 semaines</span> chez la femme allaitante</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Micro-progestatifs</strong> ✅</td>\n            <td>\n              <ul>\n                <li><strong>Quand ?</strong> en continu <strong>à partir du 21<sup>e</sup> jour</strong> (voie orale ou implant)</li>\n                <li><strong>Inconvénients :</strong> métrorragies, spottings (taches de sang en dehors des règles)</li>\n                <li><strong>Avantages :</strong> pas de répercussions métaboliques/systémiques, effet sur l’<span class=\"kw-ci\">allaitement</span> et l’enfant négligeable</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Stérilisation</strong></td>\n            <td>\n              <ul>\n                <li><strong>Quand ?</strong> au moment d’une césarienne, ou dans les <span class=\"kw-chiffre\">24–48 h</span> après un accouchement non compliqué</li>\n                <li><strong>Vigilance :</strong> <span class=\"kw-alerte\">stérilisation s’accompagne plus souvent de regrets en post-partum immédiat</span></li>\n                <li><strong>Avantage :</strong> n’allonge pas l’<span class=\"kw-alerte\">hospitalisation</span>. Taux d’échec <span class=\"kw-chiffre\">0,5–1 %</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Méthode MAMA (<span class=\"kw-ci\">allaitement</span> maternel et aménorrhée)</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>MAMA — méthode naturelle pendant les 6 premiers mois</strong>\n        <ul>\n          <li><strong>Principe :</strong> <span class=\"kw-ci\">allaitement</span> <strong>exclusif à la demande</strong>, jour et nuit + persistance d’une aménorrhée</li>\n          <li><strong>Efficacité :</strong> indice de Pearl à <span class=\"kw-chiffre\">7 %</span> (taux <span class=\"kw-ci\">grossesse</span> à<span class=\"kw-chiffre\"> 1 an</span>)</li>\n          <li><strong>Conseil :</strong> associer une contraception locale (préservatifs, spermicides) pour potentialiser l’efficacité</li>\n          <li><strong>Précaution :</strong> <span class=\"kw-alerte\">allaitement doit être exclusif</span>, sinon une méthode fiable est nécessaire</li>\n        </ul>\n      </div>\n\n      <h4>Contraception et <span class=\"kw-ci\">allaitement</span> — résumé</h4>\n\n      <table >\n        <thead>\n          <tr><th>Méthode</th><th>Compatibilité avec l’allaitement</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Œstro-progestatifs</strong></td><td><span class=\"kw-alerte\">❌ Pas recommandés</span> — risque thromboembolique + diminution de la production lactée</td></tr>\n          <tr><td><strong>Micro-progestatifs, implants progestatifs</strong></td><td>✅ Utilisables sans inconvénient</td></tr>\n          <tr><td><strong>DIU</strong></td><td>✅ Sans danger</td></tr>\n          <tr><td><strong>Préservatifs, spermicides</strong></td><td>✅ Utilisables (efficacité limitée, contraignants)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Risque d’ovulation au cours de l’<span class=\"kw-ci\">allaitement</span></h4>\n\n      <table >\n        <thead>\n          <tr><th>Situation</th><th>6 sem.</th><th>9 sem.</th><th>12 sem.</th><th>18 sem.</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-ci\">Allaitement</span> en cours</strong></td><td><span class=\"kw-chiffre\">0 %</span></td><td><span class=\"kw-chiffre\">1 %</span></td><td><span class=\"kw-chiffre\">17 %</span></td><td><span class=\"kw-chiffre\">36 %</span></td></tr>\n          <tr><td><strong><span class=\"kw-ci\">Allaitement</span> &lt; <span class=\"kw-chiffre\">6 semaines</span></strong></td><td><span class=\"kw-chiffre\">12 %</span></td><td><span class=\"kw-chiffre\">79 %</span></td><td><span class=\"kw-chiffre\">99 %</span></td><td>—</td></tr>\n          <tr><td><strong><span class=\"kw-ci\">Allaitement</span> &lt; <span class=\"kw-chiffre\">4 semaines</span></strong></td><td><span class=\"kw-chiffre\">14 %</span></td><td><span class=\"kw-chiffre\">89 %</span></td><td><span class=\"kw-chiffre\">99,5 %</span></td><td>—</td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception · obj-13 (suites de couches) · obj-14 (PEC post-partum) · 34 — Suites de couches pathologiques</em></p>","frequence":2}],"astuces":[],"strategie":{"hospit":"<p><strong>Outil :</strong> <span class=\"kw-def\">partogramme</span> — <span class=\"kw-def\">surveillance</span> clinique + paraclinique <span class=\"kw-chiffre\">au minimum toutes les heures</span> pendant le travail.</p><ul><li>Toucher vaginal aseptique toutes les <span class=\"kw-chiffre\">30 min – 1 h</span> : présentation et variété, état de la poche des eaux, <span class=\"kw-def\">score de Bishop</span> (dilatation, effacement, consistance, position du col, hauteur de la présentation)</li><li>Palpation abdominale (présentation longitudinale / transversale) ; <span class=\"kw-clinique\">hauteur utérine</span> ≈ <span class=\"kw-chiffre\">33 cm</span> hors contraction</li><li><span class=\"kw-imagerie\">Cardiotocographe</span> : RCF en <span class=\"kw-chiffre\">surveillance continue</span> pendant les 2 premiers stades + tocographie (CU : hypo/hypercinésie, hypo/hypertonie)</li><li><span class=\"kw-imagerie\">Échographie</span> en salle si besoin : présentation, quantité de LA, insertion placentaire</li><li><span class=\"kw-ttt\">Antibioprophylaxie anti-SGB</span> chez les femmes à risque (pénicilline G, <span class=\"kw-ttt\">amoxicilline</span>, ampicilline, céfazoline)</li><li><span class=\"kw-alerte\">Hospitalisation</span> possible jusqu’au <span class=\"kw-chiffre\">12ᵉ jour</span> (prise en charge sécurité sociale)</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Liquide amniotique méconial</span> (vert ± sombre) → signe d’<span class=\"kw-alerte\">état fœtal non rassurant</span> (toute émission de méconium avant la naissance traduit une pathologie)</li><li>LA <span class=\"kw-clinique\">épais ou teinté</span> → évoquer une <span class=\"kw-etio\">chorioamniotite</span></li><li><span class=\"kw-alerte\">Rupture prématurée des membranes</span> (avant tout travail) → risque d’<span class=\"kw-etio\">infection</span> + <span class=\"kw-alerte\">procidence du cordon</span> → <span class=\"kw-ttt\">hospitalisation immédiate</span></li><li>Après <span class=\"kw-alerte\">rupture</span> artificielle des membranes : <span class=\"kw-ttt\">réexaminer</span> pour vérifier l’absence de <span class=\"kw-alerte\">procidence du cordon</span></li><li>Anomalies des CU : <span class=\"kw-alerte\">hypercinésie / hypertonie</span> (risque d’hypoxie fœtale par baisse des échanges utéro-placentaires)</li><li><span class=\"kw-alerte\">Circulaire du cordon serré</span> à la sortie de la tête → section entre 2 pinces Kocher</li><li>Stagnation de la dilatation : <span class=\"kw-chiffre\">&lt; 1 cm/4 h</span> (<span class=\"kw-chiffre\">5–7 cm</span>) ou <span class=\"kw-chiffre\">&lt; 1 cm/2 h</span> (<span class=\"kw-chiffre\">7 cm</span> → complète) → <span class=\"kw-alerte\">dystocie dynamique</span></li><li>Post-partum : <span class=\"kw-alerte\">utérus mal involué</span> / perte du « globe de sécurité » → <span class=\"kw-etio\">atonie utérine</span>, <span class=\"kw-etio\">endométrite du post-partum</span>, <span class=\"kw-alerte\">HPP</span> (≥ <span class=\"kw-chiffre\">500 mL</span>)</li></ul>","principes":"<p><strong>Moteur :</strong> les <span class=\"kw-def\">contractions utérines</span> assurent la dilatation du col et la descente du fœtus dans la filière pelvienne ; <span class=\"kw-ttt\">analgésie péridurale</span> possible dès le début du travail.</p><ul><li><strong>1ᵉʳ <span class=\"kw-def\">stade</span> (dilatation)</strong> : phase de latence (→<span class=\"kw-chiffre\"> 5–6 cm</span>) puis phase active jusqu’à dilatation complète (<span class=\"kw-chiffre\">10 cm</span>)</li><li><strong><span class=\"kw-alerte\">Rupture</span> artificielle des membranes</strong> : possible si dilatation <span class=\"kw-chiffre\">&gt; 6 cm</span> et présentation engagée (aide la marche du travail)</li><li><strong>2ᵉ <span class=\"kw-def\">stade</span> (expulsion)</strong> : efforts expulsifs concomitants des CU, <span class=\"kw-chiffre\">≤ 30 min</span> ; vérifier l’absence de circulaire du cordon à la sortie de la tête</li><li><strong>3ᵉ <span class=\"kw-def\">stade</span> (délivrance dirigée)</strong> : <span class=\"kw-ttt\">ocytocine 5–10 UI IV</span> au dégagement des épaules → prévention de l’hémorragie de la délivrance ; examen systématique du placenta</li><li><strong>Hémostase</strong> : rétraction utérine = phénomène des <span class=\"kw-def\">ligatures vivantes</span> (efficace seulement après vacuité utérine totale)</li><li><strong>Prévention MTEV</strong> : bas de contention ± <span class=\"kw-ttt\">HBPM prophylactique</span> (6–8 sem) ou <span class=\"kw-ttt\">AVK ≥ 3 mois</span> selon le niveau de risque</li><li><strong>Allo-immunisation Rh</strong> : test de Kleihauer puis <span class=\"kw-ttt\">Ig anti-D &lt; 72 h</span> si mère Rh− et enfant Rh+</li></ul>","suivi":"<p><strong>Durée :</strong> suites de couches ≈ <span class=\"kw-chiffre\">6 semaines (40 j)</span>, de la <span class=\"kw-chiffre\">2ᵉ heure</span> post-accouchement jusqu’au retour de couches.</p><ul><li><strong><span class=\"kw-def\">Surveillance</span> clinique quotidienne</strong> : constantes, seins (tension, crevasses), involution du globe utérin, cicatrisation périnéale, <span class=\"kw-clinique\">lochies</span> (abondance, aspect, odeur), membres inférieurs (phlébite), appareil urinaire ; cicatrice si césarienne</li><li><strong>Involution utérine</strong> : favorisée par les <span class=\"kw-ttt\">ocytociques</span> et l’<span class=\"kw-clinique\">allaitement</span> ; tranchées douloureuses chez la <span class=\"kw-clinique\">multipare</span></li><li><strong>Lochies</strong> : sanglantes <span class=\"kw-chiffre\">J1–J4</span> → claires vers <span class=\"kw-chiffre\">J10</span> ; « petit retour de couches » possible vers <span class=\"kw-chiffre\">J20</span></li><li><strong>Retour de couches</strong> : vers <span class=\"kw-chiffre\">J45</span> (6 sem) sans <span class=\"kw-ci\">allaitement</span> ; <span class=\"kw-chiffre\">4–6 mois</span> si allaitement maternel</li><li><strong>Objectifs du séjour</strong> : contrôler l’involution + l’absence d’hémorragie, contrôler l’<span class=\"kw-ci\">allaitement</span>, dépister infections et MTEV, soins du périnée, information (rééducation pelvi-périnéale, contraception)</li></ul>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Travail confirmé — CU régulières + modifications du col (effacement, dilatation) — péridurale possible · partogramme ≥ 1×/h · RCF continu","detail":"<h4>Conduite de l’accouchement normal — Progression des stades du travail et CAT à la délivrance</h4>","branches":[{"to":"q-dilat","label":"1ᵉʳ stade · dilatation du col (latence → phase active jusqu’à 10 cm)","color":"amber"}]},{"id":"q-dilat","kind":"decision","label":"Vitesse de dilatation en phase active normale ? — anormale si <span class=\"kw-chiffre\">< 1</span> cm/4 h (5–7 cm) ou < 1 cm/2 h (7 cm → complète)","branches":[{"to":"q-presentation","label":"Oui — dilatation complète (10 cm)","color":"green"},{"to":"t-dystocie","label":"Non — stagnation de la dilatation","color":"amber"}]},{"id":"q-presentation","kind":"decision","label":"2ᵉ stade — présentation engagée compatible avec la voie basse ? — Sommet (occiput) ou face (menton) = Ø 9,5 cm → VB · Front / épaule (transverse) → césarienne","branches":[{"to":"q-delivrance","label":"Présentation eutocique (sommet / face) engagée","color":"green"},{"to":"t-cesar","label":"Présentation dystocique : front ou épaule (transverse)","color":"blue"}]},{"id":"q-delivrance","kind":"decision","label":"3ᵉ <span class=\"kw-def\">stade</span> — délivrance spontanée < <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>30</span> min</span>, placenta complet ? — Délivrance dirigée : ocytocine 5–10 UI IV au dégagement des épaules","branches":[{"to":"t-normal","label":"Oui — délivrance complète + globe de sécurité","color":"green"},{"to":"t-da","label":"Non — délivrance > 30 min","color":"amber"},{"to":"t-hpp","label":"Placenta incomplet ou HPP ≥ 500 mL","color":"red"}]},{"id":"t-normal","kind":"terminal","label":"Accouchement normal — surveillance 2 h (4ᵉ stade)","color":"green","detail":"<h4>Expulsion</h4><ul><li>Efforts expulsifs <span class=\"kw-chiffre\">≤ 30 min</span>, concomitants des CU</li><li>Vérifier l’absence de <span class=\"kw-alerte\">circulaire du cordon</span> ; clampage retardé (> <span class=\"kw-chiffre\">30 s</span>) recommandé</li></ul><h4>Délivrance</h4><ul><li><span class=\"kw-ttt\">Ocytocine 5–10 UI IV</span> (délivrance dirigée)</li><li>Examen du placenta : cotylédons complets, <span class=\"kw-chiffre\">2 artères + 1 veine</span></li></ul><h4>4ᵉ <span class=\"kw-def\">stade</span></h4><ul><li><span class=\"kw-def\">Surveillance</span> <span class=\"kw-chiffre\">2 h</span> en salle : constantes, saignement, <span class=\"kw-def\">globe de sécurité</span></li><li>Expression utérine 2–3× ; 1ʳᵉ mise au sein <span class=\"kw-chiffre\">&lt; 30 min</span></li></ul><h4>Post-partum</h4><ul><li>Prévention <span class=\"kw-ttt\">anti-D</span> (Rh) et <span class=\"kw-ttt\">MTEV</span> — voir cards « Stratégie de prise en charge »</li></ul>"},{"id":"t-da","kind":"terminal","label":"Délivrance artificielle + révision utérine","color":"amber","detail":"<h4>Indication</h4><ul><li>Patiente non délivrée après <span class=\"kw-chiffre\">30 min</span></li></ul><h4>Geste</h4><ul><li><span class=\"kw-ttt\">Délivrance artificielle</span> (extraction manuelle du placenta)</li><li>Suivie d’une <span class=\"kw-ttt\">révision utérine</span> (contrôle de la vacuité)</li></ul>"},{"id":"t-hpp","kind":"terminal","label":"Révision utérine — hémorragie du post-partum","color":"red","detail":"<h4>Définition</h4><ul><li>Sang perdu ≥ <span class=\"kw-chiffre\">500 mL</span>, ou placenta incomplet (cotylédon manquant / sac membraneux absent)</li></ul><h4>CAT</h4><ul><li><span class=\"kw-ttt\">Révision utérine</span> en <span class=\"kw-alerte\">urgence</span></li><li><span class=\"kw-ttt\">Ocytociques</span> + prise en charge de l’HPP (hors item — l’accouchement « normal » est dépassé)</li></ul>"},{"id":"t-cesar","kind":"terminal","label":"Césarienne requise","color":"blue","detail":"<h4>Indications</h4><ul><li><span class=\"kw-alerte\">Front</span> (Ø syncipito-mentonnier, trop grand)</li><li><span class=\"kw-alerte\">Présentation de l’épaule</span> / transversale (repère : acromion)</li></ul><h4>Note</h4><ul><li>Sort du cadre de l’accouchement eutocique par voie basse</li></ul>"},{"id":"t-dystocie","kind":"terminal","label":"Dystocie dynamique — réévaluation","color":"amber","detail":"<h4>Gestes</h4><ul><li><span class=\"kw-ttt\">Rupture artificielle des membranes</span> si membranes intactes (aide la marche du travail)</li><li>Correction par <span class=\"kw-ttt\">ocytocine</span> selon le contexte</li></ul><h4>Note</h4><ul><li>Anomalie de progression → sort de l’accouchement « normal » (bilan de dystocie)</li></ul>"}]},"cards":[]};